    ("boton: 'Desprevenida', quien: 'Infantería alemana en marcha',\n      txt: 'HQs, trenes, unidades desprevenidas (sin flecha ni AV a la vista, como esta infantería en marcha) y unidades en Screen no tienen ZOC. Se puede pasar a su lado sin detenerse.',\n      ef: { leg: ['Sin efecto'], truck: ['Sin efecto'], tac: ['Sin efecto'], hq: ['Sin efecto'] } },",
     "boton: 'Unprepared', quien: 'German infantry on the march',\n      txt: 'HQs, trains, Unprepared units (no arrow and no AV showing, like this infantry on the march) and Screening units have no ZOC. You can move right past them without stopping.',\n      ef: { leg: ['No effect'], truck: ['No effect'], tac: ['No effect'], hq: ['No effect'] } },"),
    ("boton: 'Infantería', quien: 'Infantería alemana desplegada',\n      txt: 'Cualquier unidad de combate sin AV, como esta infantería desplegada. Solo llega a los hexes adyacentes y frena a todo lo que no es táctico.',\n      ef: { leg: ['STOP', 'y no puede pasar a otra EZOC'], truck: ['STOP', 'y no puede pasar a otra EZOC'], tac: ['Sin efecto', 'la ignora'], hq: ['No puede entrar', 'salvo que una unidad amiga la anule'] } },",
     "boton: 'Infantry', quien: 'Deployed German infantry',\n      txt: 'Any combat unit without an AV, like this deployed infantry. It only reaches the adjacent hexes and stops everything that is not Tac.',\n      ef: { leg: ['STOP', 'and cannot move on to another EZOC'], truck: ['STOP', 'and cannot move on to another EZOC'], tac: ['No effect', 'it ignores it'], hq: ['Cannot enter', 'unless a friendly unit negates it'] } },"),
    ("boton: 'Host con apoyo', quien: 'Infantería alemana con apoyo de tanques',\n      txt: 'Un host con apoyo de su formación (aquí, Red Support) tiene ZOC blindada, sea cual sea el tipo de apoyo. Detiene también a los tanques, pero el Stopping Engagement es opcional, salvo que el apoyo sea Stand Off.',\n      ef: { leg: ['STOP'], truck: ['STOP'], tac: ['STOP', 'puede hacer un Stopping Engagement para seguir (obligatorio si el apoyo es Stand Off)'], hq: ['No puede entrar', 'salvo que una unidad amiga la anule'] } },",
     "boton: 'Supported host', quien: 'German infantry with tank Support',\n      txt: 'A host with its formation\\'s Support (here, Red Support) has an AV ZOC, whatever the Support type. It stops tanks too, but the Stopping Engagement is optional unless the Support is Stand Off.',\n      ef: { leg: ['STOP'], truck: ['STOP'], tac: ['STOP', 'it may make a Stopping Engagement to keep going (required if the Support is Stand Off)'], hq: ['Cannot enter', 'unless a friendly unit negates it'] } },"),
    ("boton: 'Unidad AV', quien: 'Panther alemán, alcance 3',\n      txt: 'Una unidad AV en el mapa, como este Panther. Su ZOC blindada sigue siendo solo de un hex, pero además proyecta una zona de enfrentamiento hasta su alcance (3), que el terreno que bloquea recorta.',\n      ef: { leg: ['STOP', 'en la ZOC', 'Sin efecto', 'en la zona de enfrentamiento'], truck: ['STOP', 'en la ZOC', 'STOP', 'también en la zona de enfrentamiento'], tac: ['STOP', 'y Stopping Engagement obligatorio: si no lo gana, se queda', 'Sin efecto', 'en la zona de enfrentamiento'], hq: ['No puede entrar', 'en la ZOC, salvo que la anule una amiga', 'No puede entrar', 'ni acabar una retirada en la zona; las amigas no la anulan'] } },",
     "boton: 'AV unit', quien: 'German Panther, range 3',\n      txt: 'An AV unit on the map, like this Panther. Its AV ZOC still reaches only one hex, but it also projects an Engagement Zone out to its range (3), which Blocking Terrain cuts short.',\n      ef: { leg: ['STOP', 'in the ZOC', 'No effect', 'in the Engagement Zone'], truck: ['STOP', 'in the ZOC', 'STOP', 'in the Engagement Zone too'], tac: ['STOP', 'and a required Stopping Engagement: if it does not win, it stays', 'No effect', 'in the Engagement Zone'], hq: ['Cannot enter', 'the ZOC, unless a friendly unit negates it', 'Cannot enter', 'or end a retreat in the zone; friendly units do not negate it'] } },"),
    ("boton: 'Pantalla', quien: 'Reconocimiento alemán en Screen',\n      txt: 'Un reconocimiento en Screen no tiene ZOC: tiene una zona de pantalla de 3 hexes que ignora terreno y unidades. Solo frena a quien va en su cara de movimiento.',\n      ef: { leg: ['+1 MP', 'por hex si va en cara de movimiento; desplegada puede entrar en su hex y echarla'], truck: ['+1 MP', 'por hex en cara de movimiento; no puede entrar en su hex'], tac: ['+1 MP', 'por hex en cara de movimiento; no puede entrar en su hex'], hq: ['Sin efecto', 'la pantalla no es una ZOC: un HQ puede entrar en su zona'] } }",
     "boton: 'Screen', quien: 'Screening German recon',\n      txt: 'A Screening recon unit has no ZOC: it has a 3-hex Screen Zone that ignores terrain and units. It only slows units on their Move-side.',\n      ef: { leg: ['+1 MP', 'per hex on the Move-side; Deployed, it can enter the Screen\\'s hex and push it out'], truck: ['+1 MP', 'per hex on the Move-side; it cannot enter the Screen\\'s hex'], tac: ['+1 MP', 'per hex on the Move-side; it cannot enter the Screen\\'s hex'], hq: ['No effect', 'a Screen is not a ZOC: an HQ can enter its zone'] } }"),
